using System;
using System.IO;
using System.Security.Principal;
using System.Threading;
using System.Collections.Concurrent;
using System.Security.AccessControl;
using System.Runtime.InteropServices;

namespace FileProcessingService
{
    public class AuditEntry
    {
        public DateTime Timestamp { get; set; }
        public string User { get; set; }
        public string Action { get; set; }
        public string Resource { get; set; }
        public bool Authorized { get; set; }
    }

    public class SecurityContext
    {
        private static readonly AsyncLocal<WindowsIdentity> _impersonatedIdentity = new AsyncLocal<WindowsIdentity>();
        private static readonly ConcurrentDictionary<string, string> _tokenCache = new ConcurrentDictionary<string, string>();

        public static WindowsIdentity CurrentIdentity => _impersonatedIdentity.Value;

        public static void SetImpersonation(WindowsIdentity identity)
        {
            _impersonatedIdentity.Value = identity;
        }

        public static string ResolveEffectiveRole(WindowsIdentity identity, string resource)
        {
            if (identity == null) return "anonymous";

            string cacheKey = $"{identity.Name}:{resource}";
            if (_tokenCache.TryGetValue(cacheKey, out string cachedRole))
                return cachedRole;

            string role = DetermineRole(identity, resource);
            _tokenCache.TryAdd(cacheKey, role);
            return role;
        }

        private static string DetermineRole(WindowsIdentity identity, string resource)
        {
            var principal = new WindowsPrincipal(identity);
            if (principal.IsInRole(WindowsBuiltInRole.Administrator))
                return "admin";
            if (principal.IsInRole(WindowsBuiltInRole.PowerUser))
                return "operator";
            return "user";
        }
    }

    public class AuthorizationPolicy
    {
        private readonly string[] _adminPaths = { @"C:\ServiceData\Config", @"C:\ServiceData\System" };
        private readonly string[] _operatorPaths = { @"C:\ServiceData\Processing", @"C:\ServiceData\Output" };
        private readonly string[] _userPaths = { @"C:\ServiceData\Input", @"C:\ServiceData\Public" };

        public bool Evaluate(string role, string normalizedPath, string operation)
        {
            string[] allowedPaths = GetAllowedPaths(role);
            bool pathAllowed = false;

            foreach (var allowed in allowedPaths)
            {
                if (normalizedPath.StartsWith(allowed, StringComparison.OrdinalIgnoreCase))
                {
                    pathAllowed = true;
                    break;
                }
            }

            if (!pathAllowed) return false;

            return operation switch
            {
                "read" => true,
                "write" => role == "admin" || role == "operator",
                "delete" => role == "admin",
                "execute" => role == "admin",
                _ => false
            };
        }

        private string[] GetAllowedPaths(string role)
        {
            return role switch
            {
                "admin" => CombineArrays(_adminPaths, _operatorPaths, _userPaths),
                "operator" => CombineArrays(_operatorPaths, _userPaths),
                "user" => _userPaths,
                _ => Array.Empty<string>()
            };
        }

        private string[] CombineArrays(params string[][] arrays)
        {
            int total = 0;
            foreach (var a in arrays) total += a.Length;
            var result = new string[total];
            int offset = 0;
            foreach (var a in arrays) { Array.Copy(a, 0, result, offset, a.Length); offset += a.Length; }
            return result;
        }
    }

    public class FileProcessor
    {
        private readonly AuthorizationPolicy _policy = new AuthorizationPolicy();
        private readonly ConcurrentQueue<AuditEntry> _auditLog = new ConcurrentQueue<AuditEntry>();
        private readonly SemaphoreSlim _processLock = new SemaphoreSlim(1, 1);

        public (bool success, string message) ProcessFileRequest(
            WindowsIdentity requestor, string filePath, string operation)
        {
            string normalizedPath = NormalizePath(filePath);
            string effectiveRole = SecurityContext.ResolveEffectiveRole(requestor, normalizedPath);

            var auditEntry = new AuditEntry
            {
                Timestamp = DateTime.UtcNow,
                User = requestor?.Name ?? "anonymous",
                Action = operation,
                Resource = normalizedPath
            };

            bool authorized = _policy.Evaluate(effectiveRole, normalizedPath, operation);
            auditEntry.Authorized = authorized;
            _auditLog.Enqueue(auditEntry);

            if (!authorized)
                return (false, $"Access denied for {effectiveRole} on {operation}:{normalizedPath}");

            return ExecuteOperation(requestor, normalizedPath, operation);
        }

        private string NormalizePath(string inputPath)
        {
            string expanded = Environment.ExpandEnvironmentVariables(inputPath);
            string full = Path.GetFullPath(expanded);
            // Resolve any trailing separators for consistent comparison
            if (!full.EndsWith(Path.DirectorySeparatorChar.ToString()) && Directory.Exists(full))
                full += Path.DirectorySeparatorChar;
            return full;
        }

        private (bool, string) ExecuteOperation(
            WindowsIdentity requestor, string path, string operation)
        {
            _processLock.Wait();
            try
            {
                // Re-validate authorization with current identity context
                SecurityContext.SetImpersonation(requestor);
                string currentRole = RevalidateAccess(path);

                switch (operation)
                {
                    case "read":
                        if (File.Exists(path))
                            return (true, File.ReadAllText(path));
                        return (false, "File not found");
                    case "write":
                        File.WriteAllText(path, $"Processed by {requestor?.Name} at {DateTime.UtcNow}");
                        return (true, "Write successful");
                    case "delete":
                        if (File.Exists(path)) File.Delete(path);
                        return (true, "Delete successful");
                    case "execute":
                        return ExecuteFile(path, currentRole);
                    default:
                        return (false, "Unknown operation");
                }
            }
            finally
            {
                SecurityContext.SetImpersonation(null);
                _processLock.Release();
            }
        }

        private string RevalidateAccess(string path)
        {
            var identity = SecurityContext.CurrentIdentity;
            if (identity == null) return "anonymous";
            return SecurityContext.ResolveEffectiveRole(identity, path);
        }

        private (bool, string) ExecuteFile(string path, string role)
        {
            if (role != "admin")
                return (false, "Execution requires admin role");

            var psi = new System.Diagnostics.ProcessStartInfo
            {
                FileName = path,
                UseShellExecute = false,
                RedirectStandardOutput = true,
                CreateNoWindow = true
            };
            using var proc = System.Diagnostics.Process.Start(psi);
            string output = proc.StandardOutput.ReadToEnd();
            proc.WaitForExit();
            return (true, output);
        }
    }

    public class ServiceEndpoint
    {
        private readonly FileProcessor _processor = new FileProcessor();

        public string HandleRequest(string username, string filePath, string operation)
        {
            WindowsIdentity identity = null;
            try
            {
                // In production, identity comes from authenticated connection
                identity = WindowsIdentity.GetCurrent();
            }
            catch { }

            var (success, message) = _processor.ProcessFileRequest(identity, filePath, operation);
            return success ? $"OK: {message}" : $"DENIED: {message}";
        }
    }
}
